import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.Element;
import org.joget.apps.form.model.FormData;
import org.joget.apps.form.model.FormRow;
import org.joget.apps.form.model.FormRowSet;
import org.joget.apps.form.service.FormUtil;

import java.util.Calendar;

public FormRowSet load(Element element, String primaryKey, FormData formData) {
    FormRowSet rows = new FormRowSet();

    // Add default value "--"
    FormRow defaultOption = new FormRow();
    defaultOption.setProperty(FormUtil.PROPERTY_VALUE, "--");
    defaultOption.setProperty(FormUtil.PROPERTY_LABEL, "--");
    rows.add(defaultOption);

    int currentYear = Calendar.getInstance().get(Calendar.YEAR);
    for (int year = currentYear; year >= 1950; year--) {
        // Ensure we don't go out of bounds by checking the next year
        if (year > 1950) {
            FormRow option = new FormRow();
            String range =  year + " / " + (year + 1);
            option.setProperty(FormUtil.PROPERTY_VALUE, range);
            option.setProperty(FormUtil.PROPERTY_LABEL, range);
            rows.add(option);
        }
    }

    return rows;
}

// Call load method with injected variables
return load(element, primaryKey, formData);

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.Element;
import org.joget.apps.form.model.Form;
import org.joget.apps.form.model.FormData;
import org.joget.apps.form.service.FormUtil;
import org.joget.commons.util.LogUtil;

private String getFieldValue(Form form, FormData formData, String fieldId) {
    Element field = FormUtil.findElement(fieldId, form, formData);
    String[] values = FormUtil.getElementPropertyValues(field, formData);
    return (values != null && values.length > 0) ? values[0] : "";
}

public boolean validate(Element element, FormData formData, String[] values) {
    boolean result = true;
    int count = 0;

    Form form = FormUtil.findRootForm(element);

    // Retrieve form field values
    String periode = getFieldValue(form, formData, "periode");
    String anneeUniv = getFieldValue(form, formData, "annee_universitaire");
    String cin = getFieldValue(form, formData, "numero_cin");

    // Correct way to get current record ID
    String id_current = formData.getPrimaryKeyValue();

    LogUtil.warn("periode", periode);
    LogUtil.warn("anneeUniv", anneeUniv);
    LogUtil.warn("cin", cin);
    LogUtil.warn("id_current", id_current);

    try {
        // Set up database connection and query
        DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
        Connection con = ds.getConnection();

        PreparedStatement stmt;
        if (id_current == null || id_current.isEmpty()) {
            // INSERT case
            stmt = con.prepareStatement(
                "SELECT COUNT(*) FROM app_fd_enseignants WHERE c_numero_cin = ? AND c_periode = ? AND c_annee_universitaire = ? AND c_enseignant = 'Permanents' AND c_active = '1'"
            );
            stmt.setString(1, cin);
            stmt.setString(2, periode);
            stmt.setString(3, anneeUniv);
        } else {
            // UPDATE case - exclude the current record
            stmt = con.prepareStatement(
                "SELECT COUNT(*) FROM app_fd_enseignants WHERE c_numero_cin = ? AND c_periode = ? AND c_annee_universitaire = ? AND c_enseignant = 'Permanents' AND c_active = '1' AND id != ?"
            );
            stmt.setString(1, cin);
            stmt.setString(2, periode);
            stmt.setString(3, anneeUniv);
            stmt.setString(4, id_current);
        }

        // Execute query and get count
        ResultSet rs = stmt.executeQuery();
        if (rs.next()) {
            count = rs.getInt(1);
        }

    } catch (SQLException e) {
        LogUtil.error("Validation error: Failed to execute database query", e);
        result = false; // Consider invalid if DB error
    }

    LogUtil.warn("count", String.valueOf(count));

    if (count > 0) {
        result = false;
        String id = FormUtil.getElementParameterName(element);
        formData.addFormError(id, "Cet enseignant est déjà un enseignant permanent dans un autre établissement pour la même période.");
    }

    return result;
}

return validate(element, formData, values);
